/* @lc app=leetcode id=3698 lang=kotlin */ class Solution { fun splitArray(nums: IntArray): Long = nums.size.let { n -> nums.indices.runningFold(true) { ok, i -> ok && (i == 0 || nums[i] > nums[i - 1]) }.let { inc -> (n - 1 downTo 0).runningFold(true) { ok, i -> ok && (i == n - 1 || nums[i] > nums[i + 1]) }.let { dec -> nums.runningFold(0L) { a, b -> a + b }.let { pre -> (1 until n).filter { inc[it] && dec[n - it] }.minOfOrNull { Math.abs(pre[it] - (pre[n] - pre[it])) } ?: -1L } } } } }